package echo

import (
	"errors"
	"fmt"
	"math/rand"
	"net/http"
	"regexp"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// Temporary reproduction test for TestRouterNoRoutablePath behaviour.
// ---------------------------------------------------------------------------

type tmpRefRoute struct {
	method  string
	pattern string
	skey    string
	vec     []int
	re      *regexp.Regexp
	idx     int
}

func tmpNormalize(pattern string) (skey string, vec []int, re *regexp.Regexp) {
	segs := strings.Split(strings.TrimPrefix(pattern, "/"), "/")
	vec = make([]int, 0, len(segs))
	parts := make([]string, 0, len(segs))
	keys := make([]string, 0, len(segs))
	for _, s := range segs {
		switch {
		case s == "*":
			vec = append(vec, 2)
			parts = append(parts, ".*")
			keys = append(keys, "*")
		case strings.HasPrefix(s, ":"):
			vec = append(vec, 1)
			parts = append(parts, "[^/]+")
			keys = append(keys, ":")
		default:
			vec = append(vec, 0)
			parts = append(parts, regexp.QuoteMeta(s))
			keys = append(keys, s)
		}
	}
	re = regexp.MustCompile("^/" + strings.Join(parts, "/") + "$")
	skey = strings.Join(keys, "/")
	return
}

func tmpLess(a, b []int) bool {
	for i := 0; i < len(a) && i < len(b); i++ {
		if a[i] != b[i] {
			return a[i] < b[i]
		}
	}
	return len(a) < len(b)
}

func tmpRouteList(routes []tmpRefRoute) string {
	s := make([]string, 0, len(routes))
	for _, r := range routes {
		s = append(s, r.method+" "+r.pattern)
	}
	return "[" + strings.Join(s, ", ") + "]"
}

func TestTmpNoRoutableFuzz(t *testing.T) {
	rnd := rand.New(rand.NewSource(1))
	statics := []string{"a", "b", "c"}
	methods := []string{http.MethodGet, http.MethodPost}
	probeSegs := []string{"a", "b", "c", "x"}

	for iter := 0; iter < 2000; iter++ {
		e := New()
		var routes []tmpRefRoute
		seen := map[string]bool{}
		nRoutes := 1 + rnd.Intn(6)
		for i := 0; i < nRoutes; i++ {
			nSeg := 1 + rnd.Intn(3)
			segs := make([]string, 0, nSeg)
			for j := 0; j < nSeg; j++ {
				switch rnd.Intn(5) {
				case 0, 1, 2:
					segs = append(segs, statics[rnd.Intn(len(statics))])
				case 3:
					segs = append(segs, fmt.Sprintf(":p%d", j))
				case 4:
					if j == nSeg-1 {
						segs = append(segs, "*")
					} else {
						segs = append(segs, statics[rnd.Intn(len(statics))])
					}
				}
			}
			pattern := "/" + strings.Join(segs, "/")
			method := methods[rnd.Intn(len(methods))]
			skey, vec, re := tmpNormalize(pattern)
			key := method + " " + skey
			if seen[key] {
				continue
			}
			seen[key] = true
			idx := len(routes)
			h := func(c Context) error { return fmt.Errorf("route-%d", idx) }
			e.router.Add(method, pattern, h)
			routes = append(routes, tmpRefRoute{method, pattern, skey, vec, re, idx})
		}

		for p := 0; p < 25; p++ {
			nSeg := rnd.Intn(5)
			segs := make([]string, 0, nSeg)
			for j := 0; j < nSeg; j++ {
				segs = append(segs, probeSegs[rnd.Intn(len(probeSegs))])
			}
			path := "/" + strings.Join(segs, "/")
			if nSeg > 0 && rnd.Intn(4) == 0 {
				path += "/"
			}
			method := methods[rnd.Intn(len(methods))]

			// reference expectation
			best := -1
			for i := range routes {
				if routes[i].re.MatchString(path) {
					if best == -1 || tmpLess(routes[i].vec, routes[best].vec) {
						best = i
					}
				}
			}
			wantIdx := -1
			wantStatus := 0
			if best == -1 {
				wantStatus = http.StatusNotFound
			} else {
				for i := range routes {
					if routes[i].skey == routes[best].skey && routes[i].method == method {
						wantIdx = i
					}
				}
				if wantIdx == -1 {
					wantStatus = http.StatusMethodNotAllowed
				}
			}

			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Fatalf("PANIC iter=%d method=%s path=%s routes=%v: %v", iter, method, path, tmpRouteList(routes), r)
					}
				}()
				c := e.NewContext(nil, nil)
				e.router.Find(method, path, c)
				err := c.Handler()(c)
				switch {
				case wantStatus == http.StatusNotFound:
					if err != ErrNotFound {
						t.Fatalf("iter=%d method=%s path=%s routes=%v: want 404, got handler err=%v (matched path=%q)", iter, method, path, tmpRouteList(routes), err, c.Path())
					}
				case wantStatus == http.StatusMethodNotAllowed:
					if err != ErrMethodNotAllowed {
						t.Fatalf("iter=%d method=%s path=%s routes=%v: want 405, got handler err=%v (matched path=%q)", iter, method, path, tmpRouteList(routes), err, c.Path())
					}
				default:
					wantErr := fmt.Sprintf("route-%d", wantIdx)
					if err == nil || err.Error() != wantErr {
						t.Fatalf("iter=%d method=%s path=%s routes=%v: want handler %s, got err=%v (matched path=%q)", iter, method, path, tmpRouteList(routes), wantErr, err, c.Path())
					}
				}
			}()
		}
	}
}

// Deterministic scenarios: paths that cannot be routed.
func TestTmpNoRoutableScenarios(t *testing.T) {
	newEcho := func() (*Echo, map[string]HandlerFunc) {
		e := New()
		h := map[string]HandlerFunc{}
		for _, p := range []string{"/static", "/static/:param", "/static/:param/static", "/static/:param/static/:param2", "/static/*"} {
			pat := p
			h[pat] = func(c Context) error { return errors.New("hit " + pat) }
			e.router.Add(http.MethodGet, pat, h[pat])
		}
		e.router.Add(http.MethodPost, "/static/:param", func(c Context) error { return errors.New("hit POST /static/:param") })
		return e, h
	}

	check := func(e *Echo, method, path string, wantErr error) {
		c := e.NewContext(nil, nil)
		e.router.Find(method, path, c)
		err := c.Handler()(c)
		if wantErr != nil {
			if err != wantErr {
				t.Fatalf("%s %s: want %v, got %v (matched %q)", method, path, wantErr, err, c.Path())
			}
			return
		}
		if err == nil || !strings.HasPrefix(err.Error(), "hit ") {
			t.Fatalf("%s %s: want a route handler, got %v (matched %q)", method, path, err, c.Path())
		}
	}

	e, _ := newEcho()
	check(e, http.MethodGet, "/static", nil)
	check(e, http.MethodGet, "/static/1", nil)
	check(e, http.MethodGet, "/static/1/static", nil)
	check(e, http.MethodGet, "/static/1/static/2", nil)
	check(e, http.MethodGet, "/static/1/2/3", nil)
