	check(e, http.MethodDelete, "/static/1", ErrMethodNotAllowed)
	check(e, http.MethodDelete, "/static/1/2/3", ErrMethodNotAllowed)
	check(e, http.MethodDelete, "/static/1/static/2/3", ErrNotFound)
	check(e, http.MethodPost, "/static/1", nil)
	check(e, http.MethodPost, "/static/1/static", ErrMethodNotAllowed)
}
