			headers: http.Header{HeaderXForwardedProto: []string{"invalid"}},
			want:    "http",
		},
		{
			name: "invalid X-Forwarded-Proto falls back to X-Forwarded-Protocol",
			headers: http.Header{
				HeaderXForwardedProto:    []string{"invalid"},
				HeaderXForwardedProtocol: []string{"https"},
			},
			want: "https",
		},
		{
			name: "all invalid falls back to http",
			headers: http.Header{
				HeaderXForwardedProto:    []string{"invalid"},
				HeaderXForwardedProtocol: []string{"invalid"},
				HeaderXForwardedSsl:      []string{"invalid"},
				HeaderXUrlScheme:         []string{"invalid"},
			},
			want: "http",
		},
		{
			name:    "X-Forwarded-Proto https",
			headers: http.Header{HeaderXForwardedProto: []string{"https"}},
			want:    "https",
		},
		{
			name:    "X-Forwarded-Protocol http",
			headers: http.Header{HeaderXForwardedProtocol: []string{"http"}},
			want:    "http",
		},
		{
			name:    "X-Forwarded-Ssl on",
			headers: http.Header{HeaderXForwardedSsl: []string{"on"}},
			want:    "https",
		},
		{
			name:    "X-Url-Scheme https",
			headers: http.Header{HeaderXUrlScheme: []string{"https"}},
			want:    "https",
		},
		{
			name: "TLS set",
			tls:  true,
			want: "https",
		},
		{
			name: "no headers",
			want: "http",
		},
		{
			name:    "valid value returned verbatim",
			headers: http.Header{HeaderXForwardedProto: []string{"HTTPS"}},
			want:    "HTTPS",
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
