cd /echo && cat > zz_tmp_sem_test.go <<'EOF'
package echo

import (
	"fmt"
	"net/http"
	"testing"
)

func TestTmpSemantics(t *testing.T) {
	cases := []struct {
		routes []string
		path   string
	}{
		{[]string{"/a/:p/b"}, "/a//b"},
		{[]string{"/a/:p"}, "/a/"},
		{[]string{"/a/:p/:q"}, "/a/b/"},
		{[]string{"/a/:p/"}, "/a//"},
		{[]string{"/a/:p"}, "/a/b/c"},
		{[]string{"/a/:p", "/a/:p/b"}, "/a//b"},
		{[]string{"/a/*"}, "/a"},
		{[]string{"/a/*"}, "/a/"},
		{[]string{"/a/*"}, "/a/b/c"},
		{[]string{"/a/:p", "/a/b"}, "/a/b"},
		{[]string{"/a/:p", "/a/b"}, "/a/c"},
		{[]string{"/a/:p/c", "/a/b"}, "/a/b/c"},
		{[]string{"/a/:p/c", "/a/*"}, "/a/b/c"},
		{[]string{"/a/:p/c", "/a/*"}, "/a/b/d"},
		{[]string{"/:p"}, "/"},
		{[]string{"/"}, "/"},
		{[]string{"/"}, "/x"},
		{[]string{"/a"}, "/a/"},
		{[]string{"/a/b", "/a/bc"}, "/a/bc"},
		{[]string{"/a/b", "/a/bc"}, "/a/b"},
		{[]string{"/a/b", "/a/bc"}, "/a/bcd"},
		{[]string{"/ab", "/a/*"}, "/ab"},
		{[]string{"/ab", "/a/*"}, "/abc"},
		{[]string{"/ab", "/a/*"}, "/a/b"},
	}
	for _, tc := range cases {
		e := New()
		for _, p := range tc.routes {
			e.router.Add(http.MethodGet, p, func(c Context) error { return nil })
		}
		c := e.NewContext(nil, nil).(*context)
		func() {
			defer func() {
				if r := recover(); r != nil {
					fmt.Printf("routes=%v path=%-12s PANIC %v\n", tc.routes, tc.path, r)
				}
			}()
			e.router.Find(http.MethodGet, tc.path, c)
			err := c.handler(c)
			fmt.Printf("routes=%-32v path=%-12s -> path=%-16q params=%v err=%v\n", tc.routes, tc.path, c.Path(), c.ParamNames(), err)
		}()
	}
}
EOF
go test . -run 'TestTmpSemantics' -v 2>&1 | head -40

