// tmpNormalize builds a permissive reference matcher for a pattern:
//   - static segment -> literal
//   - ":name" -> [^/]+ when it is the last segment (trailing param can not be empty),
//     [^/]* otherwise (echo allows empty param value when a child node consumes the rest)
//   - "*" -> .* (only generated as last segment)
func tmpNormalize(pattern string) (skey string, vec []int, re *regexp.Regexp, pnames []string) {
	segs := strings.Split(strings.TrimPrefix(pattern, "/"), "/")
	vec = make([]int, 0, len(segs))
	parts := make([]string, 0, len(segs))
	keys := make([]string, 0, len(segs))
	for i, s := range segs {
		switch {
		case s == "*":
			vec = append(vec, 2)
			parts = append(parts, "(.*)")
			keys = append(keys, "*")
			pnames = append(pnames, "*")
		case strings.HasPrefix(s, ":"):
			vec = append(vec, 1)
			if i == len(segs)-1 {
				parts = append(parts, "([^/]+)")
			} else {
				parts = append(parts, "([^/]*)")
			}
			keys = append(keys, ":")
			pnames = append(pnames, s[1:])
		default:
			vec = append(vec, 0)
			parts = append(parts, regexp.QuoteMeta(s))
			keys = append(keys, s)
		}
	}
	re = regexp.MustCompile("^/" + strings.Join(parts, "/") + "$")
	skey = strings.Join(keys, "/")
	return
