		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		tmpDump(t, "204", rec)
		if rec.Code != http.StatusNoContent {
			t.Errorf("204: code = %d", rec.Code)
		}
		if ce := rec.Header().Get(echo.HeaderContentEncoding); ce != "" {
			t.Errorf("204: Content-Encoding = %q, want empty", ce)
		}
		if rec.Body.Len() != 0 {
			t.Errorf("204: body = %q, want empty", rec.Body.Bytes())
		}
	}

	// (a2) 204 via direct middleware call
	{
		e := echo.New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		c := e.NewContext(req, rec)
		h := Gzip()(func(c echo.Context) error { return c.NoContent(http.StatusNoContent) })
		if err := h(c); err != nil {
			t.Fatalf("204 direct: %v", err)
		}
		tmpDump(t, "204-direct", rec)
		if rec.Header().Get(echo.HeaderContentEncoding) != "" {
			t.Errorf("204 direct: Content-Encoding = %q, want empty", rec.Header().Get(echo.HeaderContentEncoding))
		}
		if rec.Body.Len() != 0 {
			t.Errorf("204 direct: body = %q, want empty", rec.Body.Bytes())
		}
	}

	// (b) 200 with empty body
	{
		e := echo.New()
		e.Use(Gzip())
		e.GET("/", func(c echo.Context) error { return c.String(http.StatusOK, "") })
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		tmpDump(t, "200-empty", rec)
		if rec.Code != http.StatusOK {
			t.Errorf("200 empty: code = %d", rec.Code)
		}
		body := rec.Body.Bytes()
		ce := rec.Header().Get(echo.HeaderContentEncoding)
		if len(body) == 0 {
			if ce != "" {
				t.Errorf("200 empty: empty body but Content-Encoding = %q", ce)
			}
		} else {
			if ce != gzipScheme {
				t.Errorf("200 empty: non-empty body (%d bytes) but Content-Encoding = %q", len(body), ce)
			}
			r, err := gzip.NewReader(bytes.NewReader(body))
			if err != nil {
				t.Errorf("200 empty: body is not a valid gzip stream: %v (raw=%q)", err, body)
			} else {
				out, err := ioutil.ReadAll(r)
				r.Close()
				if err != nil {
					t.Errorf("200 empty: gzip read: %v", err)
				}
				if len(out) != 0 {
					t.Errorf("200 empty: decompressed = %q, want empty", out)
				}
			}
		}
	}

	// (b2) 200 empty body, direct middleware call
	{
		e := echo.New()
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		c := e.NewContext(req, rec)
		h := Gzip()(func(c echo.Context) error { return c.String(http.StatusOK, "") })
		if err := h(c); err != nil {
			t.Fatalf("200 empty direct: %v", err)
		}
		tmpDump(t, "200-empty-direct", rec)
		body := rec.Body.Bytes()
		ce := rec.Header().Get(echo.HeaderContentEncoding)
		if len(body) == 0 && ce != "" {
			t.Errorf("200 empty direct: empty body but Content-Encoding = %q", ce)
		}
		if len(body) > 0 {
			if ce != gzipScheme {
				t.Errorf("200 empty direct: body %d bytes but Content-Encoding = %q", len(body), ce)
			}
			r, err := gzip.NewReader(bytes.NewReader(body))
			if err != nil {
				t.Errorf("200 empty direct: not a valid gzip stream: %v (raw=%q)", err, body)
			} else {
				r.Close()
			}
		}
	}

	// (c) 304 Not Modified
	{
		e := echo.New()
		e.Use(Gzip())
		e.GET("/", func(c echo.Context) error { return c.NoContent(http.StatusNotModified) })
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		tmpDump(t, "304", rec)
		if rec.Code != http.StatusNotModified {
			t.Errorf("304: code = %d", rec.Code)
		}
		if ce := rec.Header().Get(echo.HeaderContentEncoding); ce != "" {
			t.Errorf("304: Content-Encoding = %q, want empty", ce)
		}
		if rec.Body.Len() != 0 {
			t.Errorf("304: body = %q, want empty", rec.Body.Bytes())
		}
	}

	// (d) HEAD request with no body
	{
		e := echo.New()
		e.Use(Gzip())
		e.HEAD("/", func(c echo.Context) error { return c.NoContent(http.StatusOK) })
		req := httptest.NewRequest(http.MethodHead, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		tmpDump(t, "HEAD", rec)
		if rec.Body.Len() != 0 {
			t.Errorf("HEAD: body = %q, want empty", rec.Body.Bytes())
		}
	}

	// (e) non-empty body still round-trips
	{
		e := echo.New()
		e.Use(Gzip())
		e.GET("/", func(c echo.Context) error { return c.String(http.StatusOK, "test") })
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.Header.Set(echo.HeaderAcceptEncoding, gzipScheme)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		tmpDump(t, "200-nonempty", rec)
		if rec.Header().Get(echo.HeaderContentEncoding) != gzipScheme {
			t.Fatalf("nonempty: Content-Encoding = %q", rec.Header().Get(echo.HeaderContentEncoding))
		}
		r, err := gzip.NewReader(rec.Body)
		if err != nil {
			t.Fatalf("nonempty: %v", err)
		}
		out, err := ioutil.ReadAll(r)
		r.Close()
		if err != nil {
			t.Fatalf("nonempty: %v", err)
		}
		if string(out) != "test" {
			t.Errorf("nonempty: got %q", out)
		}
	}
}
EOF
cd /echo && go test ./middleware/ -run 'TestTmpGzipEmpty' -v 2>&1 | tail -60
